    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] names = new String[n], types = new String[n];
        long[] times = new long[n];
        for (int i = 0; i < n; i++) {
            names[i] = st.nextToken();
            times[i] = Long.parseLong(st.nextToken());
            types[i] = st.nextToken();
        }
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Long> e : exclusiveTimes(names, times, types).entrySet())
            sb.append(e.getKey()).append(' ').append(e.getValue()).append('\n');
        System.out.print(sb);
    }
}
